import React, { useState, useEffect } from 'react'
import Typography from '@mui/material/Typography';
import Paper from '@mui/material/Paper';
import TextField from '@mui/material/TextField';
import Button from '@mui/material/Button';
import axios from 'axios';

export default function MyProfile() {

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phone: '',
    address: '',
    profileimage: null    // ✅ same as AddProduct's productimage
  })

  // ✅ Fetch Profile
  useEffect(() => {
    const token = localStorage.getItem("UserToken") || localStorage.getItem("token")

    if (!token) {
      alert("Please login first")
      window.location.href = "/login"
      return
    }

    axios.get("http://localhost:7000/user/getProfile", {
      headers: { Authorization: `Bearer ${token}` }
    })
    .then((res) => {
      const user = res.data.user || res.data.data || res.data

      setFormData({
        name: user.name || '',
        email: user.email || '',
        password: '',
        phone: user.phone || '',
        address: user.address || '',
        profileimage: null     // ✅ file input always starts empty
      })
    })
    .catch((err) => {
      console.log(err)
      alert("Failed to load profile")
    })
  }, [])

  // ✅ Same handleChange pattern as AddProduct
  const handleChange = (e) => {
    if (e.target.name === "profileimage") {
      setFormData({ ...formData, profileimage: e.target.files[0] })  // ✅ file
    } else {
      setFormData({ ...formData, [e.target.name]: e.target.value })  // ✅ text
    }
  }

  // ✅ Update Profile using FormData (same as AddProduct's handleSubmit)
  const handleUpdate = async () => {
    const token = localStorage.getItem("UserToken") || localStorage.getItem("token")

    if (!token) {
      alert("Please login first")
      return
    }

    try {
      const data = new FormData()             // ✅ same as AddProduct
      data.append("name", formData.name)
      data.append("email", formData.email)
      data.append("password", formData.password)
      data.append("phone", formData.phone)
      data.append("address", formData.address)

      if (formData.profileimage) {
        data.append("profileimage", formData.profileimage)  // ✅ only if selected
      }

      await axios.put("http://localhost:7000/user/updateProfile", data, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data"   // ✅ required for file upload
        }
      })

      alert("Profile updated successfully!")

    } catch (error) {
      console.log(error)
      alert("Update failed")
    }
  }

  return (
    <div style={{ display: "flex", justifyContent: "center", marginTop: "40px" }}>
      <Paper elevation={20} style={{ width: "590px", padding: "30px" }}>
        
        <Typography variant='h4' style={{ marginBottom: "20px" }}>
          Update Profile
        </Typography>

        <TextField
          variant='filled'
          label="Full Name"
          name='name'
          fullWidth
          value={formData.name}
          onChange={handleChange}
          style={{ marginBottom: "20px" }}
        />

        <TextField
          variant='filled'
          label="Email"
          name='email'
          fullWidth
          value={formData.email}
          onChange={handleChange}
          style={{ marginBottom: "20px" }}
        />

        <TextField
          variant='filled'
          type='password'
          label="Password"
          name='password'
          fullWidth
          value={formData.password}
          onChange={handleChange}
          style={{ marginBottom: "20px" }}
        />

        <TextField
          variant='filled'
          label="Phone"
          name='phone'
          fullWidth
          value={formData.phone}
          onChange={handleChange}
          style={{ marginBottom: "20px" }}
        />

        <TextField
          variant='filled'
          multiline
          rows={5}
          label="Shipping Address"
          name='address'
          fullWidth
          value={formData.address}
          onChange={handleChange}
          style={{ marginBottom: "20px" }}
        />

        {/* ✅ Exact same file input style as AddProduct */}
        <TextField
          name="profileimage"
          type="file"
          onChange={handleChange}
          fullWidth
          InputLabelProps={{ shrink: true }}
          style={{ marginBottom: "20px" }}
        />

        <Button variant='contained' fullWidth onClick={handleUpdate}>
          Update Profile
        </Button>

      </Paper>
    </div>
  )
}
